<?php
declare(strict_types=1);
require_once __DIR__ . '/../bootstrap.php';
Auth::requireRole('customer');

$id = (int)($_GET['id'] ?? 0);
$pdo = db();
$stmt = $pdo->prepare('SELECT o.* FROM orders o WHERE o.id=? AND o.customer_id=? LIMIT 1');
$stmt->execute([$id,(int)Auth::userId()]);
$order = $stmt->fetch();
if (!$order) { http_response_code(404); exit('Order not found.'); }

$stmt = $pdo->prepare('SELECT oi.*,p.name,p.image,sp.business_name,sp.seller_code FROM order_items oi INNER JOIN products p ON p.id=oi.product_id LEFT JOIN seller_profiles sp ON sp.user_id=oi.seller_id WHERE oi.order_id=? ORDER BY oi.id');
$stmt->execute([$id]); $items=$stmt->fetchAll();
$h=$pdo->prepare('SELECT h.*,u.name actor_name FROM order_status_history h LEFT JOIN users u ON u.id=h.actor_user_id WHERE h.order_id=? ORDER BY h.id DESC'); $h->execute([$id]); $history=$h->fetchAll();
$shipping=json_decode((string)($order['shipping_address'] ?? ''),true) ?: [];
function orderBadge(string $status): string { return match($status){ 'completed'=>'success','cancelled','refunded'=>'danger','shipped'=>'info',default=>'warning'}; }
?>

