<main class="df-wrap"><a href="<?=e(url('/customer/orders.php'))?>" style="color:var(--df);font-weight:850;text-decoration:none">← Back to orders</a><div class="df-top" style="margin-top:12px"><div><span class="df-eyebrow">ORDER DETAILS</span><h1><?=e((string)$order['order_number'])?></h1><p class="df-sub">Placed <?=e(date('d M Y · H:i',strtotime((string)$order['created_at'])))?></p></div><span class="df-badge <?=e(orderBadge((string)$order['status']))?>" style="align-self:center"><?=e(ucwords(str_replace('_',' ',(string)$order['status'])))?></span></div><div class="df-detail-grid"><section class="df-card df-section"><div class="df-section-head"><div><span class="df-eyebrow">PURCHASE</span><h2>Order items</h2></div></div><?php foreach($items as $i): ?><div class="df-order-item"><div><strong><?=e((string)$i['name'])?></strong><small><?=e((string)($i['business_name']??'Seller'))?> · Qty <?= (int)$i['quantity']?></small></div><div style="text-align:right"><strong>GH₵ <?=number_format((float)$i['subtotal'],2)?></strong><div style="margin-top:7px"><span class="df-badge <?=e(orderBadge((string)$i['fulfillment_status']))?>"><?=e(ucwords(str_replace('_',' ',(string)$i['fulfillment_status'])))?></span></div></div></div><?php endforeach; ?><div class="df-total" style="margin-top:15px"><strong>Total</strong><strong>GH₵ <?=number_format((float)$order['total'],2)?></strong></div></section><aside><section class="df-card df-section"><span class="df-eyebrow">DELIVERY</span><h2 style="margin:5px 0 12px">Delivery details</h2><p style="margin:0 0 6px"><strong><?=e((string)($shipping['full_name']??''))?></strong></p><p class="df-address"><?=e((string)($shipping['phone']??''))?><br><?=e((string)($shipping['address']??''))?><br><?=e((string)($shipping['city']??''))?>, <?=e((string)($shipping['region']??''))?></p><?php if(!empty($order['customer_note'])): ?><p class="df-address"><strong>Note:</strong> <?=e((string)$order['customer_note'])?></p><?php endif; ?></section><section class="df-card df-section" style="margin-top:18px"><span class="df-eyebrow">TIMELINE</span><h2 style="margin:5px 0 12px">Status history</h2><?php foreach($history as $x): ?><div class="df-history"><strong><?=e(ucwords(str_replace('_',' ',(string)$x['to_status'])))?></strong><small><?=e(date('d M Y · H:i',strtotime((string)$x['created_at'])))?><?php if($x['actor_name']): ?> · <?=e((string)$x['actor_name'])?><?php endif; ?></small><?php if($x['note']): ?><div class="df-muted" style="font-size:.82rem;margin-top:4px"><?=e((string)$x['note'])?></div><?php endif; ?></div><?php endforeach; ?></section></aside></div></main></body></html>
